package com.alibaba.nacos.console.handler.impl.inner.ai;

import com.alibaba.nacos.ai.service.skills.SkillOperationService;
import com.alibaba.nacos.api.exception.NacosException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit test for SkillInnerHandler uploadSkillFromZip method with targetVersion support.
 * 
 * This test validates the patch that adds optional targetVersion parameter to skill upload,
 * ensuring proper delegation to SkillOperationService with all parameters including targetVersion.
 */
@ExtendWith(MockitoExtension.class)
class SkillInnerHandlerTest {

    @Mock
    private SkillOperationService skillOperationService;

    private SkillInnerHandler skillInnerHandler;

    @BeforeEach
    void setUp() {
        skillInnerHandler = new SkillInnerHandler(skillOperationService);
    }

    /**
     * Test that uploadSkillFromZip correctly delegates to skillOperationService with targetVersion.
     * This validates the core functionality added by the patch.
     */
    @Test
    void testUploadSkillFromZipWithTargetVersion() throws NacosException {
        // Arrange
        String namespaceId = "test-namespace";
        byte[] zipBytes = "test-zip-content".getBytes();
        boolean overwrite = true;
        String targetVersion = "1.2.3";
        String expectedSkillName = "test-skill";

        when(skillOperationService.uploadSkillFromZip(eq(namespaceId), eq(zipBytes), eq(overwrite), eq(targetVersion)))
                .thenReturn(expectedSkillName);

        // Act
        String result = skillInnerHandler.uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);

        // Assert
        assertEquals(expectedSkillName, result);
        verify(skillOperationService).uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);
    }

    /**
     * Test that uploadSkillFromZip works correctly when targetVersion is null (backward compatibility).
     * This ensures existing code without targetVersion continues to work.
     */
    @Test
    void testUploadSkillFromZipWithNullTargetVersion() throws NacosException {
        // Arrange
        String namespaceId = "test-namespace";
        byte[] zipBytes = "test-zip-content".getBytes();
        boolean overwrite = false;
        String targetVersion = null;
        String expectedSkillName = "test-skill";

        when(skillOperationService.uploadSkillFromZip(eq(namespaceId), eq(zipBytes), eq(overwrite), eq(targetVersion)))
                .thenReturn(expectedSkillName);

        // Act
        String result = skillInnerHandler.uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);

        // Assert
        assertEquals(expectedSkillName, result);
        verify(skillOperationService).uploadSkillFromZip(namespaceId, zipBytes, overwrite, null);
    }

    /**
     * Test that uploadSkillFromZip works correctly when targetVersion is empty string.
     * Empty string should be passed through (service layer will handle it as no version specified).
     */
    @Test
    void testUploadSkillFromZipWithEmptyTargetVersion() throws NacosException {
        // Arrange
        String namespaceId = "test-namespace";
        byte[] zipBytes = "test-zip-content".getBytes();
        boolean overwrite = true;
        String targetVersion = "";
        String expectedSkillName = "test-skill";

        when(skillOperationService.uploadSkillFromZip(eq(namespaceId), eq(zipBytes), eq(overwrite), eq(targetVersion)))
                .thenReturn(expectedSkillName);

        // Act
        String result = skillInnerHandler.uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);

        // Assert
        assertEquals(expectedSkillName, result);
        verify(skillOperationService).uploadSkillFromZip(namespaceId, zipBytes, overwrite, "");
    }

    /**
     * Test that uploadSkillFromZip works with overwrite=false and targetVersion provided.
     * This validates the combination of both new and existing parameters.
     */
    @Test
    void testUploadSkillFromZipWithOverwriteFalseAndTargetVersion() throws NacosException {
        // Arrange
        String namespaceId = "public";
        byte[] zipBytes = "skill-package".getBytes();
        boolean overwrite = false;
        String targetVersion = "2.0.0";
        String expectedSkillName = "my-skill";

        when(skillOperationService.uploadSkillFromZip(eq(namespaceId), eq(zipBytes), eq(overwrite), eq(targetVersion)))
                .thenReturn(expectedSkillName);

        // Act
        String result = skillInnerHandler.uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);

        // Assert
        assertEquals(expectedSkillName, result);
        verify(skillOperationService).uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);
    }

    /**
     * Test that uploadSkillFromZip correctly passes through whitespace-only targetVersion.
     * The service layer should handle trimming, but we verify the parameter is passed correctly.
     */
    @Test
    void testUploadSkillFromZipWithWhitespaceTargetVersion() throws NacosException {
        // Arrange
        String namespaceId = "test-namespace";
        byte[] zipBytes = "test-zip-content".getBytes();
        boolean overwrite = true;
        String targetVersion = "  ";
        String expectedSkillName = "test-skill";

        when(skillOperationService.uploadSkillFromZip(eq(namespaceId), eq(zipBytes), eq(overwrite), eq(targetVersion)))
                .thenReturn(expectedSkillName);

        // Act
        String result = skillInnerHandler.uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);

        // Assert
        assertEquals(expectedSkillName, result);
        verify(skillOperationService).uploadSkillFromZip(namespaceId, zipBytes, overwrite, "  ");
    }

    /**
     * Test that NacosException from skillOperationService is properly propagated.
     * This ensures error handling is maintained through the delegation chain.
     */
    @Test
    void testUploadSkillFromZipPropagatesNacosException() throws NacosException {
        // Arrange
        String namespaceId = "test-namespace";
        byte[] zipBytes = "test-zip-content".getBytes();
        boolean overwrite = true;
        String targetVersion = "1.0.0";
        NacosException expectedException = new NacosException(NacosException.INVALID_PARAM, "Invalid skill package");

        when(skillOperationService.uploadSkillFromZip(eq(namespaceId), eq(zipBytes), eq(overwrite), eq(targetVersion)))
                .thenThrow(expectedException);

        // Act & Assert
        NacosException thrown = org.junit.jupiter.api.Assertions.assertThrows(NacosException.class, () -> {
            skillInnerHandler.uploadSkillFromZip(namespaceId, zipBytes, overwrite, targetVersion);
        });

        assertEquals(expectedException.getErrCode(), thrown.getErrCode());
        assertEquals(expectedException.getErrMsg(), thrown.getErrMsg());
    }
}

