@ExtendWith(MockitoExtension.class)
class SkillOperationServiceImplAutoPublishTest {

    @Mock
    private AiResourcePersistService aiResourcePersistService;

    @Mock
    private AiResourceVersionPersistService aiResourceVersionPersistService;

    @Mock
    private PublishPipelineExecutor publishPipelineExecutor;

    @Mock
    private SkillIndexManifestService manifestService;

    @Mock
    private AiResourceManager resourceManager;

    @Mock
    private Logger logger;

    private SkillOperationServiceImpl skillOperationService;

    private static final String NAMESPACE_ID = "test-namespace";
    private static final String SKILL_NAME = "test-skill";
    private static final String VERSION = "1.0.0";
    private static final String RESOURCE_TYPE_SKILL = "skill";
    private static final String AUTO_PUBLISH_KEY = "nacos.ai.skill.auto-publish-after-review.enabled";

    @BeforeEach
    void setUp() throws Exception {
        skillOperationService = new SkillOperationServiceImpl(
                aiResourcePersistService,
                aiResourceVersionPersistService,
                publishPipelineExecutor,
                manifestService,
                resourceManager
        );
        // Inject logger via reflection if needed for error logging tests
    }

    @Test
    void testOnSkillPipelineComplete_WhenApprovedAndAutoPublishEnabled_ShouldPublish() throws Exception {
        // Given
        PipelineExecutionResult result = new PipelineExecutionResult();
        result.setStatus(PipelineExecutionStatus.APPROVED);

        AiResourceVersion version = new AiResourceVersion();
        version.setStorage("{\"files\":[]}");

        SkillIndexManifest manifest = new SkillIndexManifest();
        manifest.setVersions(new HashMap<>());
        manifest.setLabels(new HashMap<>());

        try (MockedStatic<EnvUtil> envUtilMock = mockStatic(EnvUtil.class)) {
            envUtilMock.when(() -> EnvUtil.getProperty(AUTO_PUBLISH_KEY, Boolean.class, false))
                    .thenReturn(true);

            when(resourceManager.doSystemPublish(eq(NAMESPACE_ID), eq(SKILL_NAME), eq(RESOURCE_TYPE_SKILL),
                    eq(VERSION), eq(true))).thenReturn(version);
            when(manifestService.loadForUpdate(eq(NAMESPACE_ID), eq(SKILL_NAME))).thenReturn(manifest);
            doNothing().when(manifestService).write(eq(NAMESPACE_ID), eq(SKILL_NAME), any(SkillIndexManifest.class));

            // When - use reflection to call private method
            Method method = SkillOperationServiceImpl.class.getDeclaredMethod(
                    "onSkillPipelineComplete", String.class, String.class, String.class, PipelineExecutionResult.class);
            method.setAccessible(true);
            method.invoke(skillOperationService, NAMESPACE_ID, SKILL_NAME, VERSION, result);

            // Then
            verify(resourceManager, times(1)).onPipelineComplete(eq(NAMESPACE_ID), eq(SKILL_NAME),
                    eq(RESOURCE_TYPE_SKILL), eq(VERSION), eq(result));
            verify(resourceManager, times(1)).doSystemPublish(eq(NAMESPACE_ID), eq(SKILL_NAME),
                    eq(RESOURCE_TYPE_SKILL), eq(VERSION), eq(true));
            verify(manifestService, times(1)).write(eq(NAMESPACE_ID), eq(SKILL_NAME), any(SkillIndexManifest.class));

            // Verify manifest was updated with version and latest label
            ArgumentCaptor<SkillIndexManifest> manifestCaptor = ArgumentCaptor.forClass(SkillIndexManifest.class);
            verify(manifestService).write(eq(NAMESPACE_ID), eq(SKILL_NAME), manifestCaptor.capture());
            SkillIndexManifest capturedManifest = manifestCaptor.getValue();
            assertNotNull(capturedManifest.getVersions().get(VERSION));
            assertEquals(VERSION, capturedManifest.getLabels().get(AiResourceConstants.LABEL_LATEST));
        }
    }

    @Test
    void testOnSkillPipelineComplete_WhenApprovedButAutoPublishDisabled_ShouldNotPublish() throws Exception {
        // Given
        PipelineExecutionResult result = new PipelineExecutionResult();
        result.setStatus(PipelineExecutionStatus.APPROVED);

        try (MockedStatic<EnvUtil> envUtilMock = mockStatic(EnvUtil.class)) {
            envUtilMock.when(() -> EnvUtil.getProperty(AUTO_PUBLISH_KEY, Boolean.class, false))
                    .thenReturn(false);

            // When - use reflection to call private method
            Method method = SkillOperationServiceImpl.class.getDeclaredMethod(
                    "onSkillPipelineComplete", String.class, String.class, String.class, PipelineExecutionResult.class);
            method.setAccessible(true);
            method.invoke(skillOperationService, NAMESPACE_ID, SKILL_NAME, VERSION, result);

            // Then
            verify(resourceManager, times(1)).onPipelineComplete(eq(NAMESPACE_ID), eq(SKILL_NAME),
                    eq(RESOURCE_TYPE_SKILL), eq(VERSION), eq(result));
            verify(resourceManager, never()).doSystemPublish(anyString(), anyString(), anyString(),
                    anyString(), anyBoolean());
            verify(manifestService, never()).write(anyString(), anyString(), any(SkillIndexManifest.class));
        }
    }

    @Test
    void testOnSkillPipelineComplete_WhenRejected_ShouldNotPublish() throws Exception {
        // Given
