        result.setStatus(PipelineExecutionStatus.REJECTED);

        try (MockedStatic<EnvUtil> envUtilMock = mockStatic(EnvUtil.class)) {
            envUtilMock.when(() -> EnvUtil.getProperty(AUTO_PUBLISH_KEY, Boolean.class, false))
                    .thenReturn(true);

            // When - use reflection to call private method
