            method.setAccessible(true);
            method.invoke(skillOperationService, NAMESPACE_ID, SKILL_NAME, VERSION, result);

            // Then
            verify(resourceManager, times(1)).onPipelineComplete(eq(NAMESPACE_ID), eq(SKILL_NAME),
                    eq(RESOURCE_TYPE_SKILL), eq(VERSION), eq(result));
            verify(resourceManager, never()).doSystemPublish(anyString(), anyString(), anyString(),
                    anyString(), anyBoolean());
            verify(manifestService, never()).write(anyString(), anyString(), any(SkillIndexManifest.class));
        }
    }

    @Test
