/**
 * Unit test for SkillRemoteHandler uploadSkillFromZip method with targetVersion parameter.
 * 
 * This test validates the changes introduced by the patch that adds targetVersion parameter
 * to the skill upload API chain, ensuring backward compatibility and proper delegation.
 */
@ExtendWith(MockitoExtension.class)
class SkillRemoteHandlerTest {

    @Mock
    private NacosMaintainerClientHolder clientHolder;

