     * Test that uploadSkillFromZip accepts the new targetVersion parameter.
     * This validates the method signature change introduced by the patch.
     * Note: The current implementation delegates to the 3-parameter service method.
     */
    @Test
    void testUploadSkillFromZipWithTargetVersion() throws NacosException {
        // Arrange
        String namespaceId = "test-namespace";
        byte[] zipBytes = "test-zip-content".getBytes();
        boolean overwrite = true;
        String targetVersion = "1.2.3";
